<script setup lang="ts">
import { ref } from 'vue'
import { Activity, Eye, EyeOff, LockKeyhole, UserRound } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import { useUserStore } from '@/stores/user'
const username=ref(''), password=ref(''), visible=ref(false), busy=ref(false), error=ref('')
const route=useRoute(), router=useRouter(), user=useUserStore()
async function submit(){if(busy.value)return;error.value='';busy.value=true;try{await user.signIn(username.value,password.value);await router.replace(typeof route.query.redirect==='string'?route.query.redirect:'/dashboard')}catch(e:any){error.value=e.response?.data?.message||'登录失败，请检查账号和密码'}finally{busy.value=false}}
</script>
